#include <Arduino.h>
#include "tmp117.h"

TMP117 tmp117;

void setup() {
    Serial.begin(115200);
    uint32_t t0 = millis();
    while (!Serial && millis() - t0 < 2000) {}

    Serial.println("TMP117 Temperature Sensor Demo");

    if (!tmp117.begin(Wire)) {
        Serial.println("Failed to initialize TMP117");
        while (1) {
            delay(1000);
        }
    }

    Serial.println("TMP117 initialized successfully");
    Serial.println("Reading temperature every 1 second...");
}

void loop() {
    static uint32_t last_read = 0;
    if (millis() - last_read >= 1000) {
        last_read = millis();

        float temp_c = tmp117.readTemperatureC();
        if (isnan(temp_c)) {
            Serial.println("Failed to read temperature");
        } else {
            Serial.print("Temperature: ");
            Serial.print(temp_c, 4);
            Serial.println(" °C");
        }
    }
}

