#include "tmp117.h"

bool TMP117::begin(TwoWire &wire) {
    _wire = &wire;

    // Set pins before begin - SDA on GPIO16, SCL on GPIO17
    _wire->setSDA(16);   /* FACT-002 */
    _wire->setSCL(17);   /* FACT-003 */
    _wire->begin();

    // SEQ-001: Power up delay
    delay(TMP117_POWER_UP_DELAY_MS);

    // SEQ-002: Soft reset and configuration
    // Step 1: Write SOFT_RESET = 1
    if (!writeRegister(TMP117_REG_CONFIGURATION, 0x0002)) {  // SOFT_RESET bit 1 = 1
        return false;
    }

    // Step 2: Wait for soft reset to complete
    delay(TMP117_SOFT_RESET_DELAY_MS);

    // Step 3: Read device ID
    uint16_t device_id = 0;
    if (!readDeviceId(device_id)) {
        return false;
    }
    if (device_id != TMP117_DEVICE_ID_VALUE) {
        return false;
    }

    // Step 4: Configure continuous conversion with 8 averages and 1s cycle
    // MOD = 0b00 (continuous), CONV = 0b100 (1s), AVG = 0b01 (8 averages)
    uint16_t config = 0;
    config |= (0b00 << 10);  // MOD = continuous
    config |= (0b100 << 7);  // CONV = 1s
    config |= (0b01 << 5);   // AVG = 8 averages
    if (!writeRegister(TMP117_REG_CONFIGURATION, config)) {
        return false;
    }

    _initialized = true;
    return true;
}

float TMP117::readTemperatureC() {
    if (!_initialized) {
        return NAN;
    }

    uint16_t raw = 0;
    if (!readRegister(TMP117_REG_TEMP_RESULT, raw)) {
        return NAN;
    }

    // FRM-001: TEMP_CELSIUS = LSB * 0.0078125
    int16_t LSB = static_cast<int16_t>(raw);
    float TEMP_C = LSB * 0.0078125;
    return TEMP_C;
}

bool TMP117::isConnected() {
    if (!_wire) return false;
    _wire->beginTransmission(TMP117_I2C_ADDR);
    return _wire->endTransmission() == 0;
}

bool TMP117::writeRegister(uint8_t reg, uint16_t value) {
    _wire->beginTransmission(TMP117_I2C_ADDR);
    _wire->write(reg);
    _wire->write(static_cast<uint8_t>(value >> 8));   // MSB first
    _wire->write(static_cast<uint8_t>(value & 0xFF)); // LSB
    return _wire->endTransmission() == 0;
}

bool TMP117::readRegister(uint8_t reg, uint16_t &value) {
    // Write register address
    _wire->beginTransmission(TMP117_I2C_ADDR);
    _wire->write(reg);
    if (_wire->endTransmission(false) != 0) {  // repeated start
        return false;
    }

    // Read 2 bytes
    if (_wire->requestFrom(static_cast<uint8_t>(TMP117_I2C_ADDR), static_cast<uint8_t>(2)) != 2) {
        return false;
    }

    uint8_t msb = _wire->read();
    uint8_t lsb = _wire->read();
    value = (static_cast<uint16_t>(msb) << 8) | lsb;
    return true;
}

bool TMP117::readDeviceId(uint16_t &id) {
    return readRegister(TMP117_REG_DEVICE_ID, id);
}

