#ifndef TMP117_H
#define TMP117_H

#include <Arduino.h>
#include <Wire.h>

#define TMP117_I2C_ADDR   0x48   /* FACT-001 */

#define TMP117_REG_TEMP_RESULT    0x00   /* FACT-006 */
#define TMP117_REG_CONFIGURATION  0x01   /* FACT-007 */
#define TMP117_REG_THIGH_LIMIT    0x02   /* FACT-008 */
#define TMP117_REG_TLOW_LIMIT     0x03   /* FACT-009 */
#define TMP117_REG_DEVICE_ID      0x0F   /* FACT-010 */

#define TMP117_DEVICE_ID_VALUE    0x0117   /* FACT-011 */

#define TMP117_POWER_UP_DELAY_MS     2    /* FACT-004 rounded up */
#define TMP117_SOFT_RESET_DELAY_MS   2    /* FACT-005 */

class TMP117 {
public:
    bool begin(TwoWire &wire = Wire);
    float readTemperatureC();
    bool isConnected();

private:
    TwoWire *_wire = nullptr;
    bool _initialized = false;

    bool writeRegister(uint8_t reg, uint16_t value);
    bool readRegister(uint8_t reg, uint16_t &value);
    bool readDeviceId(uint16_t &id);
};

#endif

