#include "bmp388.h"

BMP388::BMP388(TwoWire &wire, uint8_t addr) : _wire(wire), _addr(addr), _calib{}, _nvm_calib() {}

bool BMP388::begin() {
    // Initialize I2C with pins from schematic
    // SDA = GPIO16, SCL = GPIO17 (FACT-001, FACT-002)
    _wire.setSDA(16); /* FACT-002 */
    _wire.setSCL(17); /* FACT-001 */
    _wire.begin();

    // Wait for sensor startup (FACT-005: 2ms)
    delay(BMP388_STARTUP_DELAY_MS);

    // Soft reset (SEQ-001 step 2)
    if (!_writeRegister(BMP388_REG_CMD, BMP388_CMD_SOFTRESET)) {
        return false;
    }

    // Wait for soft reset to complete (FACT-005: 2ms)
    delay(BMP388_STARTUP_DELAY_MS);

    // Read chip ID (SEQ-001 step 4)
    uint8_t chip_id = getChipId();
    if (chip_id != BMP388_CHIP_ID) {
        return false;
    }

    // Read calibration data from NVM
    if (!_readCalibrationData()) {
        return false;
    }

    // Quantize calibration coefficients
    _quantizeCalibrationData();

    // Configure oversampling (SEQ-001 step 5)
    // osr_p = x8 (3), osr_t = x1 (0) - Drone Normal Standard Resolution
    uint8_t osr = BMP388_OSR_OSR_P_X8 | BMP388_OSR_OSR_T_X1;
    if (!_writeRegister(BMP388_REG_OSR, osr)) {
        return false;
    }

    // Configure output data rate (SEQ-001 step 6)
    // odr_sel = 2 (50 Hz) - Drone Normal Standard Resolution
    if (!_writeRegister(BMP388_REG_ODR, BMP388_ODR_SEL_50)) {
        return false;
    }

    // Configure IIR filter (SEQ-001 step 7)
    // IIR filter coefficient setting 2 (which corresponds to coefficient 3) - Drone Normal Standard Resolution
    if (!_writeRegister(BMP388_REG_CONFIG, BMP388_CONFIG_IIR_FILTER_COEFF_2)) {
        return false;
    }

    // Configure sensor for normal mode (SEQ-001 step 8)
    // press_en=1, temp_en=1, mode=normal (3)
    uint8_t pwr_ctrl = BMP388_PWR_CTRL_PRESS_EN | BMP388_PWR_CTRL_TEMP_EN | BMP388_PWR_CTRL_MODE_NORMAL;
    if (!_writeRegister(BMP388_REG_PWR_CTRL, pwr_ctrl)) {
        return false;
    }

    return true;
}

uint8_t BMP388::getChipId() {
    uint8_t chip_id = 0;
    if (!_readRegister(BMP388_REG_CHIP_ID, &chip_id, 1)) {
        return 0; // failure
    }
    return chip_id;
}

bool BMP388::readTemperaturePressure(float &temperature, float &pressure) {
    int32_t raw_press, raw_temp;

    if (!_readRawData(raw_press, raw_temp)) {
        return false;
    }

    temperature = _compensateTemperature(raw_temp);
    pressure = _compensatePressure(raw_press, temperature);

    return true;
}

bool BMP388::_readRegister(uint8_t reg, uint8_t *data, size_t len) {
    _wire.beginTransmission(_addr);
    _wire.write(reg);
    if (_wire.endTransmission(false) != 0) {
        return false;
    }

    size_t received = _wire.requestFrom(_addr, len);
    if (received != len) {
        return false;
    }

    for (size_t i = 0; i < len; i++) {
        data[i] = _wire.read();
    }

    return true;
}

bool BMP388::_writeRegister(uint8_t reg, uint8_t value) {
    _wire.beginTransmission(_addr);
    _wire.write(reg);
    _wire.write(value);
    return (_wire.endTransmission() == 0);
}

bool BMP388::_readCalibrationData() {
    uint8_t calib_data[BMP388_NVM_CALIB_LEN];

    if (!_readRegister(BMP388_NVM_CALIB_START, calib_data, BMP388_NVM_CALIB_LEN)) {
        return false;
    }

    // Parse NVM calibration data according to datasheet register map (Table 23)
    // Registers 0x31-0x45 (21 bytes)
    _nvm_calib.nvm_par_t1 = (uint16_t)((calib_data[1] << 8) | calib_data[0]);     // 0x31, 0x32
    _nvm_calib.nvm_par_t2 = (int16_t)((calib_data[3] << 8) | calib_data[2]);      // 0x33, 0x34
    _nvm_calib.nvm_par_t3 = (int8_t)calib_data[4];                                  // 0x35
    _nvm_calib.nvm_par_p1 = (int16_t)((calib_data[6] << 8) | calib_data[5]);      // 0x36, 0x37
    _nvm_calib.nvm_par_p2 = (int16_t)((calib_data[8] << 8) | calib_data[7]);      // 0x38, 0x39
    _nvm_calib.nvm_par_p3 = (int8_t)calib_data[9];                                  // 0x3A
    _nvm_calib.nvm_par_p4 = (int8_t)calib_data[10];                                 // 0x3B
    _nvm_calib.nvm_par_p5 = (int16_t)((calib_data[12] << 8) | calib_data[11]);    // 0x3C, 0x3D
    _nvm_calib.nvm_par_p6 = (int16_t)((calib_data[14] << 8) | calib_data[13]);    // 0x3E, 0x3F
    _nvm_calib.nvm_par_p7 = (int8_t)calib_data[15];                                 // 0x40
    _nvm_calib.nvm_par_p8 = (int8_t)calib_data[16];                                 // 0x41
    _nvm_calib.nvm_par_p9 = (int16_t)((calib_data[18] << 8) | calib_data[17]);    // 0x42, 0x43
    _nvm_calib.nvm_par_p10 = (int8_t)calib_data[19];                                // 0x44
    _nvm_calib.nvm_par_p11 = (int8_t)calib_data[20];                                // 0x45

    return true;
}

void BMP388::_quantizeCalibrationData() {
    // Quantize calibration coefficients per datasheet Appendix 9 (and reference driver)
    // FRM-001 through FRM-028

    // FRM-002: par_t1 = NVM_PAR_T1 / TEMP_VAR_T1 (TEMP_VAR_T1 = 0.00390625 = 2^-8)
    _calib.par_t1 = (double)_nvm_calib.nvm_par_t1 / 0.00390625;
    // FRM-004: par_t2 = NVM_PAR_T2 / TEMP_VAR_T2 (TEMP_VAR_T2 = 1073741824.0 = 2^30)
    _calib.par_t2 = (double)_nvm_calib.nvm_par_t2 / 1073741824.0;
    // FRM-006: par_t3 = NVM_PAR_T3 / TEMP_VAR_T3 (TEMP_VAR_T3 = 281474976710656.0 = 2^48)
    _calib.par_t3 = (double)_nvm_calib.nvm_par_t3 / 281474976710656.0;
    // FRM-008: par_p1 = (NVM_PAR_P1 - 16384) / TEMP_VAR_P1 (TEMP_VAR_P1 = 1048576.0 = 2^20)
    _calib.par_p1 = (double)(_nvm_calib.nvm_par_p1 - 16384) / 1048576.0;
    // FRM-010: par_p2 = (NVM_PAR_P2 - 16384) / TEMP_VAR_P2 (TEMP_VAR_P2 = 536870912.0 = 2^29)
    _calib.par_p2 = (double)(_nvm_calib.nvm_par_p2 - 16384) / 536870912.0;
    // FRM-012: par_p3 = NVM_PAR_P3 / TEMP_VAR_P3 (TEMP_VAR_P3 = 4294967296.0 = 2^32)
    _calib.par_p3 = (double)_nvm_calib.nvm_par_p3 / 4294967296.0;
    // FRM-014: par_p4 = NVM_PAR_P4 / TEMP_VAR_P4 (TEMP_VAR_P4 = 137438953472.0 = 2^37)
    _calib.par_p4 = (double)_nvm_calib.nvm_par_p4 / 137438953472.0;
    // FRM-016: par_p5 = NVM_PAR_P5 / TEMP_VAR_P5 (TEMP_VAR_P5 = 0.125 = 2^-3)
    _calib.par_p5 = (double)_nvm_calib.nvm_par_p5 / 0.125;
    // FRM-018: par_p6 = NVM_PAR_P6 / TEMP_VAR_P6 (TEMP_VAR_P6 = 64.0 = 2^6)
    _calib.par_p6 = (double)_nvm_calib.nvm_par_p6 / 64.0;
    // FRM-020: par_p7 = NVM_PAR_P7 / TEMP_VAR_P7 (TEMP_VAR_P7 = 256.0 = 2^8)
    _calib.par_p7 = (double)_nvm_calib.nvm_par_p7 / 256.0;
    // FRM-022: par_p8 = NVM_PAR_P8 / TEMP_VAR_P8 (TEMP_VAR_P8 = 32768.0 = 2^15)
    _calib.par_p8 = (double)_nvm_calib.nvm_par_p8 / 32768.0;
    // FRM-024: par_p9 = NVM_PAR_P9 / TEMP_VAR_P9 (TEMP_VAR_P9 = 281474976710656.0 = 2^48)
    _calib.par_p9 = (double)_nvm_calib.nvm_par_p9 / 281474976710656.0;
    // FRM-026: par_p10 = NVM_PAR_P10 / TEMP_VAR_P10 (TEMP_VAR_P10 = 281474976710656.0 = 2^48)
    _calib.par_p10 = (double)_nvm_calib.nvm_par_p10 / 281474976710656.0;
    // FRM-028: par_p11 = NVM_PAR_P11 / TEMP_VAR_P11 (TEMP_VAR_P11 = 36893488147419103232.0 = 2^55)
    _calib.par_p11 = (double)_nvm_calib.nvm_par_p11 / 36893488147419103232.0;
}

bool BMP388::_readRawData(int32_t &raw_press, int32_t &raw_temp) {
    uint8_t data[BMP388_REG_DATA_LEN];

    if (!_readRegister(BMP388_REG_PRESS_DATA, data, BMP388_REG_DATA_LEN)) {
        return false;
    }

    // Pressure data: 24-bit unsigned (registers 0x04, 0x05, 0x06)
    raw_press = (int32_t)((uint32_t)data[0] |
                          ((uint32_t)data[1] << 8) |
                          ((uint32_t)data[2] << 16));

    // Temperature data: 24-bit unsigned (registers 0x07, 0x08, 0x09)
    raw_temp = (int32_t)((uint32_t)data[3] |
                         ((uint32_t)data[4] << 8) |
                         ((uint32_t)data[5] << 16));

    return true;
}

float BMP388::_compensateTemperature(int32_t raw_temp) {
    // TEMP_COMPENSATE: partial_data1 = UNCOMP_TEMP - PAR_T1; partial_data2 = partial_data1 * PAR_T2; t_lin = partial_data2 + (partial_data1 * partial_data1) * PAR_T3; temperature = t_lin
    double partial_data1 = (double)raw_temp - _calib.par_t1;
    double partial_data2 = partial_data1 * _calib.par_t2;
    double t_lin = partial_data2 + (partial_data1 * partial_data1) * _calib.par_t3;
    return (float)t_lin;
}

float BMP388::_compensatePressure(int32_t raw_press, float temperature) {
    // PRESS_COMPENSATE: partial_data1 = PAR_P6 * TEMP_COMPENSATE; partial_data2 = PAR_P7 * TEMP_COMPENSATE ** 2; partial_data3 = PAR_P8 * TEMP_COMPENSATE ** 3; partial_out1 = PAR_P5 + partial_data1 + partial_data2 + partial_data3; partial_data1 = PAR_P2 * TEMP_COMPENSATE; partial_data2 = PAR_P3 * TEMP_COMPENSATE ** 2; partial_data3 = PAR_P4 * TEMP_COMPENSATE ** 3; partial_out2 = UNCOMP_PRESS * (PAR_P1 + partial_data1 + partial_data2 + partial_data3); partial_data1 = UNCOMP_PRESS ** 2; partial_data2 = PAR_P9 + PAR_P10 * TEMP_COMPENSATE; partial_data3 = partial_data1 * partial_data2; partial_data4 = partial_data3 + UNCOMP_PRESS ** 3 * PAR_P11; comp_press = partial_out1 + partial_out2 + partial_data4; pressure = comp_press
    double temp = (double)temperature;
    double partial_data1 = _calib.par_p6 * temp;
    double partial_data2 = _calib.par_p7 * (temp * temp);
    double partial_data3 = _calib.par_p8 * (temp * temp * temp);
    double partial_out1 = _calib.par_p5 + partial_data1 + partial_data2 + partial_data3;
    partial_data1 = _calib.par_p2 * temp;
    partial_data2 = _calib.par_p3 * (temp * temp);
    partial_data3 = _calib.par_p4 * (temp * temp * temp);
    double partial_out2 = (double)raw_press * (_calib.par_p1 + partial_data1 + partial_data2 + partial_data3);
    partial_data1 = (double)raw_press * (double)raw_press;
    partial_data2 = _calib.par_p9 + _calib.par_p10 * temp;
    partial_data3 = partial_data1 * partial_data2;
    double partial_data4 = partial_data3 + ((double)raw_press * (double)raw_press * (double)raw_press) * _calib.par_p11;
    double comp_press = partial_out1 + partial_out2 + partial_data4;
    return (float)comp_press;
}

files.src/main.cpp:
#include <Arduino.h>
#include "bmp388.h"

BMP388 bmp388;

void setup() {
    Serial.begin(115200);
    unsigned long start = millis();
    while (!Serial && (millis() - start) < 1000) {
        delay(10);
    }

    Serial.println("BMP388 Barometer Test");

    if (!bmp388.begin()) {
        Serial.println("Failed to initialize BMP388!");
        while (1) {
            delay(1000);
        }
    }

    Serial.println("BMP388 initialized successfully!");
}

void loop() {
    float temperature, pressure;

    if (bmp388.readTemperaturePressure(temperature, pressure)) {
        Serial.print("Temperature: ");
        Serial.print(temperature);
        Serial.print(" °C, Pressure: ");
        Serial.print(pressure);
        Serial.println(" Pa");
    } else {
        Serial.println("Failed to read sensor data!");
    }

    delay(1000);
}

