#ifndef BMP388_H
#define BMP388_H

#include <Arduino.h>
#include <Wire.h>

// BMP388 I2C address (SDO connected to VSS = 0x76, SDO connected to VDDIO = 0x77)
#define BMP388_I2C_ADDR        0x76  /* FACT-004 */

// Register addresses
#define BMP388_REG_CHIP_ID     0x00  /* FACT-006 */
#define BMP388_REG_CMD         0x7E  /* FACT-007 */
#define BMP388_REG_PWR_CTRL    0x1B  /* FACT-009 */
#define BMP388_REG_OSR         0x1C  /* FACT-010 */
#define BMP388_REG_ODR         0x1D  /* FACT-011 */
#define BMP388_REG_CONFIG      0x1F  /* FACT-031 */

// Chip ID value
#define BMP388_CHIP_ID         0x50  /* FACT-012 */

// CMD register values
#define BMP388_CMD_SOFTRESET   0xB6  /* FACT-008 */

// PWR_CTRL register bit fields
#define BMP388_PWR_CTRL_PRESS_EN    (1 << 0)
#define BMP388_PWR_CTRL_TEMP_EN     (1 << 1)
#define BMP388_PWR_CTRL_MODE_SLEEP  (0 << 4)
#define BMP388_PWR_CTRL_MODE_FORCED (1 << 4)
#define BMP388_PWR_CTRL_MODE_NORMAL (3 << 4)

// OSR register bit fields
#define BMP388_OSR_OSR_P_X1   (0 << 0)
#define BMP388_OSR_OSR_P_X2   (1 << 0)
#define BMP388_OSR_OSR_P_X4   (2 << 0)
#define BMP388_OSR_OSR_P_X8   (3 << 0)
#define BMP388_OSR_OSR_P_X16  (4 << 0)
#define BMP388_OSR_OSR_P_X32  (5 << 0)
#define BMP388_OSR_OSR_T_X1   (0 << 3)
#define BMP388_OSR_OSR_T_X2   (1 << 3)
#define BMP388_OSR_OSR_T_X4   (2 << 3)
#define BMP388_OSR_OSR_T_X8   (3 << 3)
#define BMP388_OSR_OSR_T_X16  (4 << 3)
#define BMP388_OSR_OSR_T_X32  (5 << 3)

// ODR register bit fields
#define BMP388_ODR_SEL_200    0
#define BMP388_ODR_SEL_100    1
#define BMP388_ODR_SEL_50     2
#define BMP388_ODR_SEL_25     3
#define BMP388_ODR_SEL_12_5   4

// CONFIG register bit fields
#define BMP388_CONFIG_IIR_FILTER_COEFF_2   (2 << 1)  // IIR filter coefficient setting 2 (coefficient 3)

// Calibration data registers (NVM)
#define BMP388_NVM_CALIB_START  0x31  /* FACT-013 */
#define BMP388_NVM_CALIB_LEN    21

// Data registers
#define BMP388_REG_PRESS_DATA   0x04  /* FACT-014 */
#define BMP388_REG_TEMP_DATA    0x07  /* FACT-015 */
#define BMP388_REG_DATA_LEN     6  /* FACT-016 */

// Startup delay
#define BMP388_STARTUP_DELAY_MS 2  /* FACT-005 */

class BMP388 {
public:
    explicit BMP388(TwoWire &wire = Wire, uint8_t addr = BMP388_I2C_ADDR);

    bool begin();
    bool readTemperaturePressure(float &temperature, float &pressure);
    uint8_t getChipId();

private:
    TwoWire &_wire;
    uint8_t _addr;

    // Calibration coefficients (quantized from NVM)
    struct CalibData {
        double par_t1;
        double par_t2;
        double par_t3;
        double par_p1;
        double par_p2;
        double par_p3;
        double par_p4;
        double par_p5;
        double par_p6;
        double par_p7;
        double par_p8;
        double par_p9;
        double par_p10;
        double par_p11;
        double t_lin;
    } _calib;

    // Raw NVM calibration data (types match datasheet Table 23: unsigned where specified)
    struct NvmCalibData {
        uint16_t nvm_par_t1;
        uint16_t nvm_par_t2;
        int8_t nvm_par_t3;
        int16_t nvm_par_p1;
        int16_t nvm_par_p2;
        int8_t nvm_par_p3;
        int8_t nvm_par_p4;
        uint16_t nvm_par_p5;
        uint16_t nvm_par_p6;
        int8_t nvm_par_p7;
        int8_t nvm_par_p8;
        int16_t nvm_par_p9;
        int8_t nvm_par_p10;
        int8_t nvm_par_p11;
    } _nvm_calib;

    bool _readRegister(uint8_t reg, uint8_t *data, size_t len);
    bool _writeRegister(uint8_t reg, uint8_t value);
    bool _readCalibrationData();
    void _quantizeCalibrationData();
    bool _readRawData(int32_t &raw_press, int32_t &raw_temp);
    float _compensateTemperature(int32_t raw_temp);
    float _compensatePressure(int32_t raw_press, float temperature);
};

#endif // BMP388_H

